using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore; using OrcaFacil.Application.Abstractions; using OrcaFacil.Application.Documents; using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.Documents; [Authorize] public class EditModel:PageModel{private readonly OrcaFacilDbContext _db; private readonly ICurrentUserService _current; private readonly DocumentService _service; public string Number{get;private set;}=""; [BindProperty] public DocumentForm Input{get;set;}=DocumentForm.Default(); public EditModel(OrcaFacilDbContext db,ICurrentUserService current,DocumentService service){_db=db;_current=current;_service=service;} public async Task<IActionResult> OnGetAsync(Guid id,CancellationToken ct){var d=await _db.Documents.Include(x=>x.Items).SingleOrDefaultAsync(x=>x.Id==id&&x.UserId==_current.UserId&&!x.IsDeleted,ct); if(d is null)return NotFound(); Number=d.Number; Input=new(){ClientName=d.ClientName,Discount=d.Discount,Notes=d.Notes,Items=d.Items.Select(i=>new DocumentItemForm{Description=i.Description,Quantity=i.Quantity,UnitPrice=i.UnitPrice,Discount=i.Discount}).ToList()}; return Page();} public async Task<IActionResult> OnPostAsync(Guid id,CancellationToken ct){var r=await _service.UpdateAsync(new(_current.UserId,id,Input.ClientName,Input.ToItems(),Input.Discount,Input.Notes),ct); if(!r.Succeeded){ModelState.AddModelError("",r.Error??"Erro ao salvar.");return Page();} return RedirectToPage("/Documents/Details",new{id});}}
